// Package mcpsdk registers the MCP Events handlers of package mcpevents on a
// server built with the official Go MCP SDK
// (github.com/modelcontextprotocol/go-sdk).
//
// Hand-written, not generated by Speakeasy: it is not tracked in
// .speakeasy/gen.lock, so it survives SDK regeneration.
package mcpsdk

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"

	"github.com/hookdeck/outpost/sdks/outpost-go/mcpevents"
	"github.com/modelcontextprotocol/go-sdk/jsonrpc"
	"github.com/modelcontextprotocol/go-sdk/mcp"
)

// ExtensionID is the extension identifier SEP-3415 advertises under
// capabilities.extensions.
const ExtensionID = "io.modelcontextprotocol/events"

// protocolModern is the first revision whose results must carry resultType.
const protocolModern = "2026-07-28"

// Options configures Register.
type Options struct {
	// ResolvePrincipal returns the authenticated subject of an MCP request,
	// for example req.GetExtra().TokenInfo.UserID behind auth.RequireBearerToken.
	// Never use the OAuth client ID: every user of one MCP client shares it.
	// Required. "" is rejected with Forbidden; a returned *mcpevents.RPCError
	// is sent as is and any other error becomes a generic internal error.
	ResolvePrincipal func(ctx context.Context, req mcp.Request) (string, error)
}

// Register adds events/list, events/subscribe and events/unsubscribe to
// server, answered by h, and advertises the events capability (the design
// sketch's top-level "events" that ChatGPT reads, and the SEP-3415
// extensions entry) on initialize and server/discover. Call it before the
// server serves any request.
func Register(server *mcp.Server, h *mcpevents.Handlers, opts Options) error {
	if server == nil || h == nil {
		return errors.New("mcpsdk: a server and handlers are required")
	}
	if opts.ResolvePrincipal == nil {
		return errors.New("mcpsdk: Options.ResolvePrincipal is required")
	}
	for _, method := range []string{mcpevents.MethodList, mcpevents.MethodSubscribe, mcpevents.MethodUnsubscribe} {
		err := mcp.AddReceivingCustomMethod(server, method,
			func(ctx context.Context, _ *mcp.ServerSession, params *rawParams) (*rawResult, error) {
				return handle(ctx, h, opts, method, params)
			})
		if err != nil {
			return err
		}
	}
	server.AddReceivingMiddleware(middleware)
	return nil
}

type requestKey struct{}

// middleware hands the request to the custom method handlers (they only get
// the params) and adds the events capability to the handshake results.
func middleware(next mcp.MethodHandler) mcp.MethodHandler {
	return func(ctx context.Context, method string, req mcp.Request) (mcp.Result, error) {
		switch method {
		case mcpevents.MethodList, mcpevents.MethodSubscribe, mcpevents.MethodUnsubscribe:
			return next(context.WithValue(ctx, requestKey{}, req), method, req)
		case "initialize", "server/discover":
			res, err := next(ctx, method, req)
			if err != nil || res == nil {
				return res, err
			}
			// server/discover exists only in the revisions requiring resultType,
			// which the SDK can't stamp on a wrapped result.
			return &capabilitiesResult{inner: res, complete: method == "server/discover"}, nil
		}
		return next(ctx, method, req)
	}
}

func handle(ctx context.Context, h *mcpevents.Handlers, opts Options, method string, params *rawParams) (*rawResult, error) {
	req, _ := ctx.Value(requestKey{}).(mcp.Request)
	if req == nil {
		// Only when another middleware dropped the context Register set up.
		return nil, wireError(h.Forbidden())
	}
	principal, err := opts.ResolvePrincipal(ctx, req)
	if err != nil {
		var rpcErr *mcpevents.RPCError
		if errors.As(err, &rpcErr) && rpcErr != nil {
			return nil, wireError(rpcErr)
		}
		h.Report(ctx, method, err)
		return nil, wireError(h.InternalError())
	}
	var raw json.RawMessage
	if params != nil {
		raw = params.raw
	}
	result, err := h.Handle(ctx, method, principal, raw)
	if err != nil {
		var rpcErr *mcpevents.RPCError
		if !errors.As(err, &rpcErr) || rpcErr == nil {
			rpcErr = h.InternalError()
		}
		return nil, wireError(rpcErr)
	}
	return &rawResult{raw: result, complete: isModern(req)}, nil
}

// wireError converts to the SDK's JSON-RPC error type: the SDK sends any
// other error with its Error() text as the message and code 0.
func wireError(e *mcpevents.RPCError) error {
	return &jsonrpc.Error{Code: e.Code, Message: e.Message, Data: e.Data}
}

func isModern(req mcp.Request) bool {
	v, ok := req.(interface{ ProtocolVersion() string })
	return ok && v.ProtocolVersion() >= protocolModern
}

// rawParams keeps the params exactly as received, for verbatim forwarding.
type rawParams struct {
	mcp.ParamsBase
	raw json.RawMessage
}

func (p *rawParams) UnmarshalJSON(data []byte) error {
	p.raw = append(json.RawMessage(nil), data...)
	// _meta too, for the SDK's per-request accessors (ProtocolVersion).
	// Malformed params are left to the handlers to reject.
	var meta struct {
		Meta map[string]any `json:"_meta"`
	}
	if json.Unmarshal(data, &meta) == nil {
		p.Meta = meta.Meta
	}
	return nil
}

// rawResult is the Outpost result, sent verbatim plus the members the SDK
// would add to its own result types: resultType on the revisions requiring
// it, and the _meta the SDK sets through SetMeta (server identity).
type rawResult struct {
	mcp.ResultBase
	raw      json.RawMessage
	complete bool
}

func (r *rawResult) MarshalJSON() ([]byte, error) {
	var extra []member
	if r.complete {
		extra = append(extra, member{"resultType", json.RawMessage(`"complete"`)})
	}
	if len(r.Meta) > 0 {
		meta, err := json.Marshal(r.Meta)
		if err != nil {
			return nil, err
		}
		extra = append(extra, member{"_meta", meta})
	}
	return addMembers(r.raw, extra)
}

// capabilitiesResult wraps an initialize or server/discover result to add
// the events capability, which mcp.ServerCapabilities can't express.
type capabilitiesResult struct {
	mcp.ResultBase
	inner    mcp.Result
	complete bool
}

func (r *capabilitiesResult) GetMeta() map[string]any  { return r.inner.GetMeta() }
func (r *capabilitiesResult) SetMeta(m map[string]any) { r.inner.SetMeta(m) }

func (r *capabilitiesResult) MarshalJSON() ([]byte, error) {
	data, err := json.Marshal(r.inner)
	if err != nil {
		return nil, err
	}
	var fields map[string]json.RawMessage
	if err := json.Unmarshal(data, &fields); err != nil {
		return nil, err
	}
	caps := map[string]json.RawMessage{}
	if raw, ok := fields["capabilities"]; ok && !bytes.Equal(raw, []byte("null")) {
		if err := json.Unmarshal(raw, &caps); err != nil {
			return nil, err
		}
	}
	if _, ok := caps["events"]; !ok {
		caps["events"] = json.RawMessage(`{}`)
	}
	extensions := map[string]json.RawMessage{}
	if raw, ok := caps["extensions"]; ok && !bytes.Equal(raw, []byte("null")) {
		if err := json.Unmarshal(raw, &extensions); err != nil {
			return nil, err
		}
	}
	if _, ok := extensions[ExtensionID]; !ok {
		extensions[ExtensionID] = json.RawMessage(`{}`)
	}
	if caps["extensions"], err = json.Marshal(extensions); err != nil {
		return nil, err
	}
	if fields["capabilities"], err = json.Marshal(caps); err != nil {
		return nil, err
	}
	if _, ok := fields["resultType"]; r.complete && !ok {
		fields["resultType"] = json.RawMessage(`"complete"`)
	}
	return json.Marshal(fields)
}

type member struct {
	name  string
	value json.RawMessage
}

// addMembers appends members missing from the JSON object obj, leaving
// everything already there byte for byte.
func addMembers(obj json.RawMessage, members []member) ([]byte, error) {
	obj = bytes.TrimSpace(obj)
	if len(members) == 0 {
		return obj, nil
	}
	var present map[string]json.RawMessage
	if len(obj) < 2 || obj[0] != '{' || json.Unmarshal(obj, &present) != nil {
		return nil, errors.New("mcpsdk: result is not a JSON object")
	}
	var buf bytes.Buffer
	buf.Write(obj[:len(obj)-1])
	empty := len(present) == 0
	for _, m := range members {
		if _, ok := present[m.name]; ok {
			continue
		}
		if !empty {
			buf.WriteByte(',')
		}
		empty = false
		name, _ := json.Marshal(m.name)
		buf.Write(name)
		buf.WriteByte(':')
		buf.Write(m.value)
	}
	buf.WriteByte('}')
	return buf.Bytes(), nil
}
